-- Schema aprovado para Game Jam Mentor. A versão completa será aplicada junto com as políticas RLS na fase Supabase.
create extension if not exists "pgcrypto";

create table if not exists public.jams (id uuid primary key default gen_random_uuid(), name text not null, region text not null, start_date date not null, end_date date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint jams_valid_period check (end_date >= start_date));
create table if not exists public.mentors (id uuid primary key default gen_random_uuid(), jam_id uuid not null references public.jams(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, name text not null, email text not null, area text not null default 'Direção de Arte', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (jam_id, user_id));
create table if not exists public.themes (id uuid primary key default gen_random_uuid(), jam_id uuid not null references public.jams(id) on delete cascade, name text not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.teams (id uuid primary key default gen_random_uuid(), jam_id uuid not null references public.jams(id) on delete cascade, name text not null, game_name text not null, theme_id uuid not null references public.themes(id) on delete restrict, engine text, description text, general_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.team_members (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, name text not null, role text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.evaluation_criteria (id uuid primary key default gen_random_uuid(), jam_id uuid not null references public.jams(id) on delete cascade, name text not null, description text, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.evaluations (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete restrict, mentor_id uuid not null references public.mentors(id) on delete restrict, final_observation text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (team_id, mentor_id));
create table if not exists public.evaluation_scores (id uuid primary key default gen_random_uuid(), evaluation_id uuid not null references public.evaluations(id) on delete cascade, criterion_id uuid not null references public.evaluation_criteria(id) on delete restrict, score integer not null check (score between 1 and 5), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (evaluation_id, criterion_id));
